class Solution {
public:
    int maxBoxesInWarehouse(vector<int>& boxes, vector<int>& warehouse) {
        sort(boxes.rbegin(), boxes.rend());
        int l = 0, r = warehouse.size() - 1;
        int ans = 0;
        for (int b : boxes) {
            if (l > r) break;
            if (warehouse[l] >= b) {
                ans++;
                l++;
            } else if (warehouse[r] >= b) {
                ans++;
                r--;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxBoxesInWarehouse(int[] boxes, int[] warehouse) {
        Arrays.sort(boxes);
        int l = 0, r = warehouse.length - 1;
        int ans = 0;
        for (int i = boxes.length - 1; i >= 0; i--) {
            int b = boxes[i];
            if (l > r) break;
            if (warehouse[l] >= b) {
                ans++;
                l++;
            } else if (warehouse[r] >= b) {
                ans++;
                r--;
            }
        }
        return ans;
    }
}

var maxBoxesInWarehouse = function(boxes, warehouse) {
    boxes.sort((a, b) => b - a);
    let l = 0, r = warehouse.length - 1;
    let ans = 0;
    for (const b of boxes) {
        if (l > r) break;
        if (warehouse[l] >= b) {
            ans++;
            l++;
        } else if (warehouse[r] >= b) {
            ans++;
            r--;
        }
    }
    return ans;
};
